const pptxgen = require("pptxgenjs");

let pres = new pptxgen();
pres.layout = 'LAYOUT_16x9'; 
pres.author = 'Gemini';

const COLOR_PRIMARY = "1E2761";
const COLOR_SECONDARY = "CADCFC";
const COLOR_ACCENT = "0088CC"; // Coral: F96167 or Teal: 00A896
const COLOR_BG_LIGHT = "F8F9FA";
const COLOR_TEXT_DARK = "333333";
const COLOR_TEXT_LIGHT = "FFFFFF";

// Master for Title Slide
pres.defineSlideMaster({
  title: 'TITLE_SLIDE',
  background: { color: COLOR_PRIMARY },
  objects: [
    { rect: { x: 0, y: 0, w: '100%', h: '100%', fill: { color: COLOR_PRIMARY } } },
    { rect: { x: 0.5, y: 0.5, w: 9, h: 4.625, line: { color: COLOR_SECONDARY, width: 2 } } }
  ]
});

// Master for Content Slides
pres.defineSlideMaster({
  title: 'CONTENT_SLIDE',
  background: { color: COLOR_BG_LIGHT },
  objects: [
    { rect: { x: 0, y: 0, w: '100%', h: 1.0, fill: { color: "FFFFFF" } } },
    { rect: { x: 0, y: 1.0, w: '100%', h: 0.05, fill: { color: COLOR_PRIMARY } } },
    { text: { text: "Source: Artificial Analysis, April 2026", options: { x: 0.5, y: 5.3, w: 5, h: 0.3, fontSize: 10, color: "888888" } } }
  ]
});

// Slide 1: Title
let slide1 = pres.addSlide({ masterName: "TITLE_SLIDE" });
slide1.addText("AI Model Landscape April 2026: Benchmarking Intelligence, Speed, and Cost Across 11 Frontier Models", {
  x: 1, y: 1.5, w: 8, h: 1.5, fontSize: 32, bold: true, color: COLOR_TEXT_LIGHT, align: "center", fontFace: "Helvetica"
});
slide1.addText([
  { text: "Gemini 3.1 Pro and GPT-5.4 tie at 57 on the Intelligence Index while a 33x pricing gap separates the cheapest and most expensive frontier models.", options: { breakLine: true } }
], { x: 1.5, y: 3.2, w: 7, h: 1, fontSize: 16, color: COLOR_SECONDARY, align: "center", fontFace: "Helvetica" });

// Slide 2: Intelligence
let slide2 = pres.addSlide({ masterName: "CONTENT_SLIDE" });
slide2.addText("Gemini 3.1 Pro Preview and GPT-5.4 Co-Lead the Intelligence Index at 57", {
  x: 0.5, y: 0.2, w: 9, h: 0.6, fontSize: 20, bold: true, color: COLOR_PRIMARY, fontFace: "Helvetica"
});

const intData = [
  { name: "Intelligence Index", labels: [
    "Gemini 3.1 Pro", "GPT-5.4", "Claude Opus 4.6", "Muse Spark", "Claude Sonnet 4.6", 
    "GLM-5.1", "Grok 4.20", "Gemini 3 Flash", "DeepSeek V3.2", "NVIDIA Nemotron 3", "gpt-oss-120B"
  ], values: [57, 57, 53, 52, 52, 51, 49, 46, 42, 36, 33] }
];

slide2.addChart(pres.charts.BAR, intData, {
  x: 0.5, y: 1.3, w: 9, h: 3.8, barDir: "col",
  chartColors: ["1E2761", "1E2761", "84B59F", "84B59F", "84B59F", "CADCFC", "CADCFC", "CADCFC", "CADCFC", "CADCFC", "CADCFC"],
  chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true },
  valGridLine: { color: "E2E8F0", size: 0.5 },
  catGridLine: { style: "none" },
  catAxisLabelColor: "64748B", valAxisLabelColor: "64748B",
  showValue: true, dataLabelPosition: "outEnd", dataLabelColor: "1E293B",
  showLegend: false
});

// Slide 3: Speed
let slide3 = pres.addSlide({ masterName: "CONTENT_SLIDE" });
slide3.addText("gpt-oss-120B Tops Output Speed at 218 Tokens/s -- More Than 4x Faster Than Claude Opus 4.6", {
  x: 0.5, y: 0.2, w: 9, h: 0.6, fontSize: 18, bold: true, color: COLOR_PRIMARY, fontFace: "Helvetica"
});

const speedData = [
  { name: "Output Tokens/s", labels: [
    "gpt-oss-120B", "Grok 4.20", "NVIDIA Nemotron 3", "Gemini 3 Flash", "Gemini 3.1 Pro", 
    "GPT-5.4", "GLM-5.1", "Claude Sonnet 4.6", "Claude Opus 4.6", "DeepSeek V3.2"
  ], values: [218, 188, 172, 153, 118, 83, 64, 63, 49, 46] }
];

slide3.addChart(pres.charts.BAR, speedData, {
  x: 0.5, y: 1.3, w: 9, h: 3.8, barDir: "bar",
  chartColors: ["00A896"],
  chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true },
  valGridLine: { color: "E2E8F0", size: 0.5 },
  catGridLine: { style: "none" },
  catAxisLabelColor: "64748B", valAxisLabelColor: "64748B",
  showValue: true, dataLabelPosition: "outEnd", dataLabelColor: "1E293B",
  showLegend: false
});

// Slide 4: Pricing
let slide4 = pres.addSlide({ masterName: "CONTENT_SLIDE" });
slide4.addText("From $0.30 to $10 per Million Tokens: A 33x Pricing Gap Across Models", {
  x: 0.5, y: 0.2, w: 9, h: 0.6, fontSize: 20, bold: true, color: COLOR_PRIMARY, fontFace: "Helvetica"
});

const priceData = [
  { name: "$/1M Tokens", labels: [
    "Claude Opus 4.6", "Claude Sonnet 4.6", "GPT-5.4", "Gemini 3.1 Pro", "Grok 4.20", 
    "GLM-5.1", "Gemini 3 Flash", "NVIDIA Nemotron 3", "DeepSeek V3.2", "gpt-oss-120B"
  ], values: [10.00, 6.00, 5.60, 4.50, 3.00, 2.10, 1.10, 0.40, 0.30, 0.30] }
];

slide4.addChart(pres.charts.BAR, priceData, {
  x: 0.5, y: 1.3, w: 9, h: 3.8, barDir: "bar",
  chartColors: ["F96167"],
  chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true },
  valGridLine: { color: "E2E8F0", size: 0.5 },
  catGridLine: { style: "none" },
  catAxisLabelColor: "64748B", valAxisLabelColor: "64748B",
  showValue: true, dataLabelPosition: "outEnd", dataLabelColor: "1E293B", dataLabelFormatCode: "$#,##0.00",
  showLegend: false
});

// Slide 5: Tradeoffs
let slide5 = pres.addSlide({ masterName: "CONTENT_SLIDE" });
slide5.addText("No Model Wins on All Three Axes: Navigating the Intelligence-Efficiency-Cost Frontier", {
  x: 0.5, y: 0.2, w: 9, h: 0.6, fontSize: 18, bold: true, color: COLOR_PRIMARY, fontFace: "Helvetica"
});

slide5.addImage({
  path: "/app/benchmark/assets/chart_intelligence_vs_output_tokens.jpg",
  x: 0.5, y: 1.3, w: 4.5, h: 3.5, sizing: { type: "contain" }
});

let tableData = [
  [{ text: "Metric", options: { fill: { color: COLOR_PRIMARY }, color: "FFFFFF", bold: true } }, 
   { text: "Proprietary Leader", options: { fill: { color: COLOR_PRIMARY }, color: "FFFFFF", bold: true } },
   { text: "Score", options: { fill: { color: COLOR_PRIMARY }, color: "FFFFFF", bold: true } },
   { text: "Open-Weight Leader", options: { fill: { color: COLOR_PRIMARY }, color: "FFFFFF", bold: true } },
   { text: "Score", options: { fill: { color: COLOR_PRIMARY }, color: "FFFFFF", bold: true } }
  ],
  ["Intelligence", "Gemini 3.1 Pro Preview", "57", "GLM-5.1", "51"],
  ["Speed (tokens/s)", "Gemini 3 Flash", "153", "gpt-oss-120B (high)", "218"],
  ["Price ($/1M)", "Gemini 3 Flash", "$1.10", "gpt-oss-120B (high)", "$0.30"]
];

slide5.addTable(tableData, { 
  x: 5.2, y: 1.8, w: 4.3, 
  border: { pt: 1, color: "E2E8F0" }, 
  fill: { color: "FFFFFF" },
  fontSize: 10,
  rowH: 0.4,
  valign: "middle"
});

slide5.addText("Proprietary vs. Open-Weight Snapshot", {
  x: 5.2, y: 1.3, w: 4.3, h: 0.4, fontSize: 14, bold: true, color: COLOR_PRIMARY
});

// Slide 6: Takeaways
let slide6 = pres.addSlide({ masterName: "CONTENT_SLIDE" });
slide6.addText("Open Weights Close the Gap: GLM-5.1 Reaches 51 Intelligence at $2.10/M Tokens", {
  x: 0.5, y: 0.2, w: 9, h: 0.6, fontSize: 18, bold: true, color: COLOR_PRIMARY, fontFace: "Helvetica"
});

slide6.addText([
  { text: "Two-way tie at the top:", options: { bold: true, breakLine: true } },
  { text: "Gemini 3.1 Pro Preview and GPT-5.4 (xhigh) both score 57 on the Intelligence Index.", options: { breakLine: true } },
  { text: "", options: { breakLine: true } },

  { text: "Speed and intelligence are inversely correlated:", options: { bold: true, breakLine: true } },
  { text: "The fastest model (gpt-oss-120B at 218 tokens/s) scores only 33 on intelligence, while the smartest models operate at 49-118 tokens/s.", options: { breakLine: true } },
  { text: "", options: { breakLine: true } },

  { text: "Massive pricing spread:", options: { bold: true, breakLine: true } },
  { text: "A 33x cost gap separates the cheapest ($0.30/1M) from the most expensive ($10.00/1M).", options: { breakLine: true } },
  { text: "", options: { breakLine: true } },

  { text: "Open-weight models are closing the gap:", options: { bold: true, breakLine: true } },
  { text: "GLM-5.1 at 51 intelligence is within 10% of proprietary leaders, but cheaper ($2.10/1M).", options: { breakLine: true } },
  { text: "", options: { breakLine: true } },

  { text: "No single model wins on all three axes:", options: { bold: true, breakLine: true } },
  { text: "Choosing requires explicit trade-offs among intelligence, speed, and cost based on use case.", options: { breakLine: true } }
], { x: 0.5, y: 1.3, w: 8, h: 3.8, fontSize: 14, color: COLOR_TEXT_DARK, valign: "top" });


pres.writeFile({ fileName: "/app/output/final_deck.pptx" }).then(() => {
  console.log("PPTX created successfully!");
}).catch((err) => {
  console.error("Error creating PPTX", err);
});
